import {esc} from './visuals.mjs';
import {coverage} from './safety-model.mjs';
import {signWorkerPosition} from './sign-worker-position.mjs';
const ui=new Map();
export const layoutSelection=site=>ui.get(site.id)||'station';
export function selectLayoutObject(site,value){if(['station','sensor','escape','obstacle','coverage','crew'].includes(value))ui.set(site.id,value);}
const button=(label,action,value,selected=false)=>`<button type="button" class="btn" data-ws="${action}" data-value="${value}" aria-pressed="${selected}">${label}</button>`;
const select=(label,key,value,options)=>`<label class="ws-field">${label}<select data-ws-input="layout.${key}">${options.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select></label>`;
const check=(label,key,value)=>`<label class="layout-toggle"><input type="checkbox" data-ws-input="layout.${key}" ${value?'checked':''}>${label}</label>`;
const number=(label,key,value,min,max,step=1)=>`<label class="ws-field">${label}<input type="number" data-ws-input="layout.${key}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
const points={west:[180,110,180,50],east:[690,265,690,335],north:[450,80,555,80]};
export function renderLayout(site){
 const l=site.layout,c=coverage(l),p=signWorkerPosition(l),selected=layoutSelection(site),[x,y,ex,ey]=points[l.entry]||points.west,escapeY=l.escape==='road'?180:ey,deviceX=45+l.cameraPosition*6.4,reach=Math.min(650,l.range*5),live=l.power&&l.localLink;
 const mark=key=>selected===key?' layout-highlight':'';
 const target=(key,label,cx,cy,shape)=>`<g class="layout-target${mark(key)}" role="button" tabindex="0" aria-label="${label}" aria-pressed="${selected===key}" data-ws="layout-object" data-value="${key}" transform="translate(${cx} ${cy})">${shape}</g>`;
 const candidates=Object.entries(points).filter(([key])=>key!=='north'||l.template==='corner').map(([key,[cx,cy]])=>`<g class="layout-target" role="button" tabindex="0" aria-label="${key} worker station" aria-pressed="${l.entry===key}" data-ws="layout-station" data-value="${key}"><circle cx="${cx}" cy="${cy}" r="20" fill="${l.entry===key?'#f5cc54':'#fff'}" stroke="#80631b" stroke-width="${l.entry===key?4:2}"/><text x="${cx}" y="${cy+5}" text-anchor="middle">S</text></g>`).join('');
 const svg=`<svg class="layout-map" viewBox="0 0 800 390" role="group" aria-label="Interactive site configuration"><defs><pattern id="layout-hatch" width="10" height="10" patternTransform="rotate(45)" patternUnits="userSpaceOnUse"><rect width="3" height="10" fill="#bc6a3370"/></pattern><marker id="layout-arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="context-stroke"/></marker></defs><rect width="800" height="390" fill="#edf3ef"/><path d="M0 180H800${l.template==='corner'?' M390 0V180':''}" stroke="#526773" stroke-width="88" fill="none"/><path d="M0 180H800" stroke="#c7d4d4" stroke-width="2" stroke-dasharray="12 10"/><path d="${p.arrow}" stroke="white" stroke-width="4" fill="none" marker-end="url(#layout-arrow)"/>
 <g class="${mark('coverage')}" opacity="${live?1:.25}"><path d="M${deviceX} 290 L${Math.max(0,deviceX-reach/2)} 138 L${Math.min(800,deviceX+reach/2)} 138 Z" fill="#319c8b30" stroke="#278c7e" stroke-dasharray="6 4"/><path d="M750 290 L${Math.max(0,750-reach)} 140 L780 220Z" fill="#319c8b30" stroke="#278c7e" stroke-dasharray="6 4"/>${l.extra?'<path d="M335 55L345 195L435 195L435 10Z" fill="#319c8b40" stroke="#278c7e"/><path d="M470 125L230 135L340 30Z" fill="#319c8b30" stroke="#278c7e"/>':''}</g>
 ${l.obstacle?`<g class="${mark('obstacle')}"><rect x="280" y="48" width="66" height="70" rx="4" fill="#9faea6"/><text x="260" y="36">Obstruction</text></g>`:''}
 ${c.gaps.length?`<g class="${mark('coverage')}"><rect x="12" y="143" width="105" height="74" fill="url(#layout-hatch)" stroke="#ac592b"/><text x="14" y="236" fill="#8b431c">Checks pending: ${c.gaps.length}</text></g>`:''}
 <rect x="475" y="235" width="160" height="35" fill="#f2ce72" stroke="#957124"/><text x="485" y="257">Restricted work area</text>
 ${target('crew','Work crew area',l.workerZone==='south'?550:650,l.workerZone==='south'?325:65,'<rect x="-55" y="-22" width="110" height="44" rx="5" fill="#fff9db" stroke="#b18b31"/><text text-anchor="middle" y="5">Work crew</text>')}
 <g class="${mark('station')}"><path d="${p.sight}" fill="none" stroke="#b58b2c" stroke-width="3" stroke-dasharray="7 5"/>${candidates}</g>
 <g class="${mark('escape')}"><path d="M${x} ${y}L${ex} ${escapeY}" fill="none" stroke="${l.escape==='road'?'#b04e32':'#237b68'}" stroke-width="4" stroke-dasharray="7 5" marker-end="url(#layout-arrow)"/><circle cx="${ex}" cy="${escapeY}" r="7" fill="${l.escape==='road'?'#b04e32':'#237b68'}"/><text x="${Math.min(650,ex-55)}" y="${escapeY+22}">${l.escape==='road'?'Traffic conflict':'Escape candidate'}</text></g>
 ${target('sensor','Select main sensor',deviceX,290,'<rect x="-16" y="-13" width="32" height="26" rx="4" fill="#247e71"/><text text-anchor="middle" y="5" fill="white">C1</text>')}
 <rect x="734" y="277" width="32" height="26" rx="4" fill="#247e71"/><text x="750" y="295" text-anchor="middle" fill="white">C2</text>
 ${l.extra?'<rect x="319" y="42" width="32" height="26" rx="4" fill="#247e71"/><text x="335" y="60" text-anchor="middle" fill="white">C3</text><rect x="454" y="112" width="32" height="26" rx="4" fill="#247e71"/><text x="470" y="130" text-anchor="middle" fill="white">C4</text>':''}
 <text x="20" y="375">Illustrative layout · not to scale${live?'':' · Sensor power / communications unavailable'}</text></svg>`;
 const issue=(text,key)=>`<button class="layout-issue" data-ws="layout-object" data-value="${key}">${esc(text)}</button>`;
 const objectText={station:p.facing,sensor:'C1 · choose an illustrative device position.',escape:'Select a same-side escape or demonstrate a traffic conflict.',obstacle:'Extra sensors do not verify the worker’s sight line.',coverage:'Conceptual coverage checks; shaded footprints are not measured sensor fields.',crew:'Work crew location is separate from the sign-holding worker.'};
 return `<section class="layout-console"><div class="layout-toolbar">${select('Road template','template',l.template,[['straight','Straight road'],['corner','Corner road']])}${select('Traffic approach','entry',l.entry,[['west','West'],['east','East'],...(l.template==='corner'?[['north','North']]:[])])}${check('Obstruction','obstacle',l.obstacle)}${check('Extra sensors','extra',l.extra)}</div><div class="layout-grid"><div class="card"><div class="card-body"><h2>Positions & sensor coverage</h2><p>Choose a worker station or select a device.</p></div>${svg}<div class="card-body layout-legend">S · sign worker　■ · camera　Amber · sight line　Green / red · escape</div></div><aside class="card"><div class="card-body"><h3>Selected: ${esc(selected)}</h3><p>${esc(objectText[selected])}</p><div class="layout-buttons">${['station','sensor','escape','crew'].map(key=>button(key==='sensor'?'Main sensor':key[0].toUpperCase()+key.slice(1),'layout-object',key,selected===key)).join('')}</div>${selected==='station'?`<div class="layout-buttons">${['west','east',...(l.template==='corner'?['north']:[])].map(key=>button(key,'layout-station',key,l.entry===key)).join('')}</div>`:''}${selected==='sensor'?`<div class="layout-buttons">${[[20,'Near entry'],[50,'Middle'],[85,'Far from entry']].map(([v,label])=>button(label,'layout-device',v,l.cameraPosition===v)).join('')}</div>`:''}${selected==='escape'?select('Escape route','escape',l.escape,[['south','Same roadside'],['road','Across traffic']]):''}${selected==='crew'?select('Work crew area','workerZone',l.workerZone,[['south','South roadside'],['north','North roadside']]):''}<h3>Worker station</h3><span class="worker-state ${p.hold?'attention':'normal'}">${p.hold?'Needs review':'Candidate · not approved'}</span>${p.reasons.map(t=>issue(t,l.escape==='road'&&t.includes('escape')?'escape':'obstacle')).join('')}<h3>Sensor configuration</h3><p>${c.cameras} cameras · ${c.radars} proposed radars · ${c.gaps.length} checks pending</p>${c.gaps.map(t=>issue(t,t.includes('Escape')?'escape':'coverage')).join('')}<p>v${l.revision} · ${l.confirmed===l.revision?'Sensor configuration confirmed':'Unconfirmed'}</p><button class="btn" data-ws="confirm-layout" ${c.gaps.length?'disabled':''}>Confirm sensor configuration</button><p class="note">Sensor checks do not approve a worker station.</p></div></aside></div><details class="ws-details" data-support-details="layout-advanced"><summary>Advanced configuration & hardware</summary><div class="card-body"><div class="ws-form">${number('C1 position (% from west entry)','cameraPosition',l.cameraPosition,0,100)}${number('Detection range (assumed m)','range',l.range,10,120)}${number('Alert lead time (assumed s)','lead',l.lead,1,15)}${number('Worker separation (assumed m)','separation',l.separation,1,10,.5)}<label class="ws-field">Valid until<input type="datetime-local" data-ws-input="layout.validUntil" value="${esc(l.validUntil)}"></label></div>${check('Local communications','localLink',l.localLink)}${check('Site power','power',l.power)}<p>Proposed hardware: fixed cameras, radar, local processing, wearable alerts, local network and backup power. Device specifications and quantities require site validation.</p><p>Coverage uses demonstration rules: additional devices address approach-count checks; range below 50 m or C1 beyond 70% leaves a check pending. Shaded areas illustrate these assumptions, not measured visibility. A qualified person must verify stopping sight distance, clearance and escape routes.</p></div></details></section>`;
}
